/* Filter Ajax*/
$(document).on(
    "keyup",
    '#filter_form input[name="search_keyword"]',
    function (e) {
        if ($(this).val().length > 2 || $(this).val().length == 0) {
            $("#filter_page").val(1);
            $("#filter_form").trigger("submit");
        }
    }
);
$(document).on("change", "#filter_form select", function () {
    $("#filter_form").trigger("submit");
});

/*Ajax Pagination*/
$(document).on("click", ".custom-pagination a.page-link", function (e) {
    e.preventDefault();
    var page_number = $(this).attr("href").split("page=")[1];
    $("#filter_page").val(page_number);
    $("#filter_form").trigger("submit");
});
/* Order by query */

/* Order by query */
$(document).on("click", ".orderby", function () {
    var column = $(this).attr("data-column");
    var orderby = $(this).attr("data-orderby");
    if (orderby == "asc") {
        orderby = "desc";
    } else {
        orderby = "asc";
    }
    $("#form-orderbycolumn").val(column);
    $("#form-orderby").val(orderby);
    $("#filter_form").trigger("submit");
});
$(document).on("submit", "#filter_form", function (e) {
    e.preventDefault();
    $("#load_content").block({
        message: '<span class="spinner-border text-primary"></span> Loading...',
        css: {
            "background-color": "none",
            background: "none",
            border: "none",
            color: "#fff",
        },
    });
    var form_data = $(this).serialize();
    var form_url = $(this).attr("action");
    $.ajax({
        type: "GET",
        url: form_url,
        dataType: "json",
        cache: false,
        data: form_data,
        success: function (data) {
            if (data.status == "success") {
                setTimeout(function () {
                    $("#load_content").html(data.content);
                    $('[data-toggle="popover"]').popover({html:true,trigger:"hover"})
                }, 1000);
            } else {
                // toastr.error(data.message);
            }
        },
        error: function () {
            setTimeout(function () {
                $("#load_content").html(data.content);
            }, 1000);
            toastr.error("Something went wrong...");
        },
    });
});
/* END Filter Ajax*/

